SELECT * FROM (SELECT CASE WHEN revenue >= 3700 THEN 'high' WHEN revenue >= 600 THEN 'mid' ELSE 'low' END AS revenue_bucket, ROUND(AVG(revenue), 2) AS avg_revenue, COUNT(DISTINCT revenue) AS unique_products FROM store_sales WHERE product_id IN (4, 6, 7, 9) GROUP BY CASE WHEN revenue >= 3700 THEN 'high' WHEN revenue >= 600 THEN 'mid' ELSE 'low' END) AS sub WHERE avg_revenue > 38 ORDER BY revenue_bucket DESC LIMIT 5;
